"""Theory courses shown in «Вчити» for moto (A, A1) and boat (BOAT) learners.

Writes feature/car/src/main/assets/courses/{moto,boat}.json. Run from the repo root.
Each step: title, text, optional bullets, note (tip), warning, facts [[label, value]], ref (source), scene (animated
illustration id from CourseScenes.kt).
"""
import json
import pathlib

PP = "Правила плавання для малих суден і водних мотоциклів"
LAW = "Закон «Про внутрішній водний транспорт»"

def step(title, text, *, bullets=None, note=None, warning=None, facts=None, ref=None, scene=None):
    d = {"title": title, "text": text}
    for k, v in (("bullets", bullets), ("note", note), ("warning", warning), ("facts", facts), ("ref", ref), ("scene", scene)):
        if v:
            d[k] = v
    return d

